43	export interface IGPUCanvasContext {
44	  configure(config: { device: IGPUDevice; format: string }): void;
45	  getCurrentTexture(): { createView(): IGPUTextureView };
46	}
47	
48	/**
49	 * The subset of `GPUDevice` this backend calls — hand-rolled (there is no
50	 * `@webgpu/types` dependency here) so tests can inject a fake without a
51	 * real GPU, same pattern as `IWebGL2Context`/`ICanvas2DContext`.
52	 */
53	export interface IGPUDevice {
54	  readonly queue: IGPUQueue;
55	  createShaderModule(descriptor: { code: string }): IGPUShaderModule;
56	  createBuffer(descriptor: { size: number; usage: number }): IGPUBuffer;
57	  createRenderPipeline(descriptor: {
58	    layout: "auto";
59	    vertex: {
60	      module: IGPUShaderModule;
61	      entryPoint: string;
62	      buffers: ReadonlyArray<{
63	        arrayStride: number;
64	        attributes: ReadonlyArray<{ shaderLocation: number; offset: number; format: string }>;
65	      }>;
66	    };
67	    fragment: {
68	      module: IGPUShaderModule;
69	      entryPoint: string;
70	      targets: ReadonlyArray<{ format: string }>;
71	    };
72	    primitive: { topology: string };
73	  }): IGPURenderPipeline;
74	  createBindGroup(descriptor: {
75	    layout: IGPUBindGroupLayout;
76	    entries: ReadonlyArray<{ binding: number; resource: { buffer: IGPUBuffer } }>;
77	  }): IGPUBindGroup;
78	  createCommandEncoder(): IGPUCommandEncoder;
79	}
80	
81	export interface IWebGPUBackendDependencies {
82	  getDevice(): IGPUDevice;
83	  getCanvasContext(): IGPUCanvasContext;
84	  /** Defaults to `"bgra8unorm"`, the platform-preferred swap chain format on most browsers. */
85	  canvasFormat?: string;
86	}
87	
88	// WebGPU spec-fixed GPUBufferUsage bit flags — not exposed on GPUDevice itself.
89	const GPU_BUFFER_USAGE_VERTEX = 0x20;
90	const GPU_BUFFER_USAGE_UNIFORM = 0x40;
91	const GPU_BUFFER_USAGE_COPY_DST = 0x8;
92	
93	const UNIFORM_BUFFER_SIZE_BYTES = 64; // 16 floats — see struct layout in WGSL_SHADER_SOURCE below.
94	const UNIFORM_FLOAT_COUNT = UNIFORM_BUFFER_SIZE_BYTES / 4;
95	
96	const UNIT_QUAD = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);
97	
98	/**
99	 * Single WGSL module (vertex + fragment) mirroring `webgl2-backend.ts`'s
100	 * GLSL topology exactly, but authored independently per ADR-004/
101	 * shader-system.md: WGSL and GLSL are never auto-shared. Struct field
102	 * order/alignment matches the 16-float `Float32Array` written per node in
103	 * `writeUniforms` below (`vec2`/`f32` @ 8/4-byte alignment, `vec4` @
104	 * 16-byte alignment per the WGSL spec).
105	 */
106	const WGSL_SHADER_SOURCE = `
107	struct Uniforms {
108	  canvasSize: vec2<f32>,
109	  translate: vec2<f32>,
110	  scale: vec2<f32>,
111	  rotation: f32,
112	  _pad0: f32,
113	  boundsOrigin: vec2<f32>,
114	  boundsSize: vec2<f32>,
115	  color: vec4<f32>,
116	};
117	@group(0) @binding(0) var<uniform> u: Uniforms;
118	
119	@vertex
120	fn vs_main(@location(0) unitQuad: vec2<f32>) -> @builtin(position) vec4<f32> {
121	  let local = u.boundsOrigin + unitQuad * u.boundsSize;
122	  let scaled = local * u.scale;
123	  let c = cos(u.rotation);
124	  let s = sin(u.rotation);
125	  let rotated = vec2<f32>(scaled.x * c - scaled.y * s, scaled.x * s + scaled.y * c);
126	  let world = rotated + u.translate;
127	  let ndc = (world / u.canvasSize) * 2.0 - vec2<f32>(1.0, 1.0);
128	  return vec4<f32>(ndc.x, -ndc.y, 0.0, 1.0);
129	}
130	
131	@fragment
132	fn fs_main() -> @location(0) vec4<f32> {
133	  return u.color;
134	}
135	`;
136	
137	/** WebGPU backend — the primary rung (`05-rendering-engine/webgpu.md`), confirmed solid 2026 browser support. */
138	export class WebGPURenderBackend implements IRenderBackend {
139	  readonly kind = RenderBackend.WebGPU;
140	
141	  private readonly dependencies: IWebGPUBackendDependencies;
142	  private device: IGPUDevice | null = null;
